package ru.kstolu.app;
import android.content.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.AtomicInteger;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class SelectionClientTest {
 private Context context;private SharedPreferences prefs;
 @Before public void setup(){context=RuntimeEnvironment.getApplication();prefs=context.getSharedPreferences("settings",0);prefs.edit().clear().commit();}
 @After public void cleanup(){ApiClient.restoreTransport();}
 private HttpURLConnection response(URL url,String body,int code,boolean lost){return new HttpURLConnection(url){public void disconnect(){}public boolean usingProxy(){return false;}public void connect(){}public OutputStream getOutputStream(){return new ByteArrayOutputStream();}public int getResponseCode()throws IOException{if(lost)throw new IOException("lost acknowledgement");return code;}public InputStream getInputStream(){return new ByteArrayInputStream(body.getBytes(StandardCharsets.UTF_8));}public InputStream getErrorStream(){return getInputStream();}};}
 private String done(){return "{\"status\":\"done\",\"result\":{\"status\":\"ok\",\"recipes\":[]}}";}
 @Test public void lostAcknowledgementRecoversWithGetOnly()throws Exception{AtomicInteger posts=new AtomicInteger(),gets=new AtomicInteger();ApiClient.configureForTests(url->{assertTrue(prefs.contains(SelectionClient.PENDING));if(url.getPath().equals("/api/selection-jobs")){posts.incrementAndGet();return response(url,"",200,true);}gets.incrementAndGet();return response(url,done(),200,false);});JSONObject out=SelectionClient.run(context,new JSONObject().put("consent",true),null);assertEquals("ok",out.getString("status"));assertEquals(1,posts.get());assertEquals(1,gets.get());assertFalse(prefs.contains(SelectionClient.PENDING));assertTrue(prefs.contains(SelectionClient.READY));}
 @Test public void appReopeningChecksSavedIdWithoutPost()throws Exception{prefs.edit().putString(SelectionClient.PENDING,"saved-selection-id-123456").commit();AtomicInteger calls=new AtomicInteger();ApiClient.configureForTests(url->{assertEquals("/api/selection-jobs/saved-selection-id-123456",url.getPath());calls.incrementAndGet();return response(url,done(),200,false);});assertEquals("ok",SelectionClient.run(context,null,null).optString("status"));assertEquals(1,calls.get());}
 @Test public void savedReadyResultNeedsNoNetwork()throws Exception{prefs.edit().putString(SelectionClient.READY,"{\"status\":\"ok\"}").commit();ApiClient.configureForTests(url->{throw new AssertionError("Paid or recovery call not needed");});assertEquals("ok",SelectionClient.run(context,null,null).optString("status"));}
 @Test public void rejectedUploadDoesNotLeaveFalsePendingJob()throws Exception{ApiClient.configureForTests(url->response(url,"{\"error\":\"Лимит\"}",429,false));try{SelectionClient.run(context,new JSONObject(),null);fail();}catch(ApiClient.ApiError e){assertEquals(429,e.status);}assertFalse(prefs.contains(SelectionClient.PENDING));}
}
